import threading

class Concert:

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.available_seats = capacity
        self.is_closed = False
        self.lock = threading.Lock()

    def reserve_seats(self, n: int) -> bool:
        with self.lock:
            if self.is_closed:
                return False
            if self.available_seats >= n:
                self.available_seats -= n
                return True
            return False

    def cancel_reservation(self, n: int) -> bool:
        with self.lock:
            if self.is_closed:
                return False
            if self.available_seats < n:
                return False
            self.available_seats += n
            self.is_closed = False
            return True

    def available_seats(self) -> int:
        with self.lock:
            if self.is_closed:
                return 0
            return self.available_seats

    def cancel_concert(self) -> None:
        with self.lock:
            self.is_closed = True
```

